import{_ as i,o as a,c as e,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"CDS Squid: RADOS","description":"","frontmatter":{"title":"CDS Squid: RADOS","date":"2023-07-25T00:00:00.000Z","updated":"2023-07-26T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可扩展性","对象存储"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/CDS_Squid_-_RADOS.md","filePath":"posts/2023/CDS_Squid_-_RADOS.md","lastUpdated":1780459816000}'),t={name:"posts/2023/CDS_Squid_-_RADOS.md"};function o(s,l,n,u,h,p){return a(),e("div",null,[...l[0]||(l[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次会议是Ceph开发者会议的延续，主要讨论了Ceph管理器（MGR）的性能问题、编码解码的可测试性、客户端之间的QoS、读取均衡器、可用性跟踪、Erasure编码配置文件的简化等议题。</p><h4 id="主要议题及讨论内容" tabindex="-1">主要议题及讨论内容 <a class="header-anchor" href="#主要议题及讨论内容" aria-label="Permalink to &quot;主要议题及讨论内容&quot;">​</a></h4><ol><li><p><strong>Op Tracker for MGR</strong></p><ul><li>讨论了在MGR中实现操作跟踪器（Op Tracker）的重要性，以监控和管理操作，尤其是在处理性能问题时。</li><li>提出了使用Python插件的性能分析工具来集成Op Tracker到MGR中的建议。</li><li>讨论了可能的技术挑战，并鼓励志愿者参与此项目。</li></ul></li><li><p><strong>编码解码的可测试性</strong></p><ul><li>讨论了编码解码框架的可测试性问题，特别是在处理客户端和服务器版本兼容性时。</li><li>提出了改进测试覆盖率的建议，包括强制注册新的可编码类，并扩展测试框架以涵盖更多场景。</li><li>讨论了如何处理不同集群模式下的版本兼容性。</li></ul></li><li><p><strong>客户端之间的QoS</strong></p><ul><li>讨论了在Ceph集群中实现客户端之间QoS的必要性和当前进展。</li><li>提出了在不同客户端之间实现公平性的方法，并讨论了相关的技术细节和挑战。</li></ul></li><li><p><strong>读取均衡器</strong></p><ul><li>讨论了将读取均衡器集成到Ceph的平衡器管理模块中的可能性，以减少用户干预。</li><li>提出了自动运行读取均衡器的建议，并讨论了可能的触发机制。</li></ul></li><li><p><strong>可用性跟踪</strong></p><ul><li>讨论了如何在Ceph中实现长期的可用性跟踪，包括定义可用性的标准。</li><li>提出了基于PG状态的可用性跟踪方法，并讨论了如何优化和扩展这一功能。</li></ul></li><li><p><strong>Erasure编码配置文件的简化</strong></p><ul><li>讨论了简化Erasure编码配置文件的需求，特别是在小型集群中的应用。</li><li>提出了创建预定义配置文件的建议，并讨论了如何使这些配置文件更易于用户使用。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>将继续推进Op Tracker在MGR中的集成工作。</li><li>将改进编码解码框架的测试覆盖率，并强制注册新的可编码类。</li><li>将继续开发客户端之间的QoS功能，并解决相关的技术挑战。</li><li>将开发自动运行的读取均衡器，并探索不同的触发机制。</li><li>将开发基于PG状态的可用性跟踪功能，并优化其性能。</li><li>将创建预定义的Erasure编码配置文件，以简化用户操作。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续推进各项议题的开发和测试工作。</li><li>定期召开会议，跟进各项议题的进展，并解决遇到的问题。</li><li>与社区成员保持沟通，收集反馈，并根据反馈调整开发计划。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>会议中提到的其他议题，如多租户统计、端到端跟踪等，将在后续的会议中进一步讨论。</li><li>鼓励社区成员积极参与讨论，提出建议和反馈。</li></ul><h4 id="会议总结" tabindex="-1">会议总结 <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结&quot;">​</a></h4><p>本次会议成功讨论了Ceph管理器及相关功能的多个关键议题，并制定了相应的行动计划。会议强调了社区合作的重要性，并鼓励所有成员积极参与，共同推动Ceph项目的发展。</p>',13)])])}const c=i(t,[["render",o]]);export{_ as __pageData,c as default};
